use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.planks();
    var labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(index: i) {
            Some(plank) => {
                if mill.rules.is_kept(plank) {
                    labels.push(item: mill.rules.to_label(plank));
                }
            },
            None => {},
        }
        i = i + 1;
    }
    labels.join(sep: ",")
}

