use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    while i < board.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        match board.get(index: i) {
            Some(dish) => {
                galley.kitchen.serve(io: io, dish: dish)?;
            },
            None => {
                unit
            },
        };
        i = i + 1;
    }
    return Ok(unit);
}

use harbor.signal;

fn to_entry(signal: harbor.signal.Signal) -> String {
    match signal {
        harbor.signal.Signal.Calm => "calm",
        harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
        harbor.signal.Signal.Fog(density) => "fog:".concat(other: density),
    }
}

pub fn entries() -> String {
    let sequence = harbor.signal.today();
    var parts: List<String> = [];
    var i = 0;
    while i < sequence.len() {
        match sequence.get(index: i) {
            Some(signal) => {
                parts.push(item: to_entry(signal))
            },
            None => unit,
        };
        i = i + 1;
    }
    parts.join(sep: ";")
}

